def rgba(name):
    if name == "clear":          # see-through (cut-out decals)
        return [0.0, 0.0, 0.0, 0.0]
    h = PALETTE[name]
    return [int(h[i:i + 2], 16) / 255.0 for i in (0, 2, 4)] + [1.0]


