# ------------------------------------------------------------------------------------------------ dressing
def shards(ctx, x0, x1, y0, y1, z, axis, rng):
    """Broken glass left in a window frame (looks only: the window is an open hole for shots)."""
    b = ctx.b
    nrm = (0, 0, 1) if axis == "x" else (1, 0, 0)

    def P(a, y):
        return (a, y, z) if axis == "x" else (z, y, a)
    for corner_a, corner_y, da, dy in ((x0, y0, 1, 1), (x1, y0, -1, 1), (x0, y1, 1, -1), (x1, y1, -1, -1)):
        if rng.random() < 0.6:
            la, ly = rng.uniform(0.15, 0.45), rng.uniform(0.15, 0.4)
            b.poly([P(corner_a, corner_y), P(corner_a + da * la, corner_y), P(corner_a, corner_y + dy * ly)], nrm, "glass",
                   uv_world(1.0))


# Openings (refine pass, owner: windows framed, some whole and some smashed; broken doors at the entrances). The
# generator lists every outside opening of the building; every model gets the same treatment.
ENTRANCE_DOOR = {"school": "wood"}
ROLLER_DOORS = set()                               # wide doors (> 3 m) with a roller shutter, drawn by the building: no leaves
SLIDING_DOORS = {}                                 # big doors that slide (kind/material, trim): the farm (0.17)                # what the front doors are made of (else an aluminium shop door)


OWN_OPENINGS = set()     # buildings that dress their own windows and doors (the bell tower: stone arches)


def dress_openings(ctx, openings):
    b = ctx.b
    for o in openings:
        kind, side, at, mid, w, lo, hi = o["kind"], o["side"], o["at"], o["mid"], o["w"], o["lo"], o["hi"]
        if BUILDING_NAME[0] in OWN_OPENINGS and kind in ("window", "door"):
            continue
        if kind == "blast":
            pass
        rng = random.Random(f"{BUILDING_NAME[0]}{side}{mid}{lo}")
        ns = side in "NS"
        out = 1 if side in "SE" else -1

        def P(a, y, d):                                 # along the wall, height, depth (+ = outwards)
            return (a, y, at + out * d) if ns else (at + out * d, y, a)

        def bx(a, y, d, la, h, ld, mat):
            b.box(P(a, y, d), (la, h, ld) if ns else (ld, h, la), style=lambda n, m, q: (mat, uv_world(1.0)))
        nrm = (0, 0, out) if ns else (out, 0, 0)
        a0, a1 = mid - w / 2, mid + w / 2
        if kind == "blast":
            dress_blast(ctx, o, P, out, ns, a0, a1, lo, hi, rng)
            continue
        if kind in ("window", "shop_window"):
            f = 0.06
            for a in (a0 + f / 2, a1 - f / 2):                                     # frame
                bx(a, (lo + hi) / 2, 0.06, f, hi - lo, 0.08, "trim")
            for y in (lo + f / 2, hi - f / 2):
                bx(mid, y, 0.06, w - 2 * f, f, 0.08, "trim")
            bx(mid, lo - 0.035, 0.19, w + 0.1, 0.08, 0.1, "concrete")               # sill outside (a hair proud)
            panes = [(a0 + f, a1 - f)]
            if kind == "shop_window" or w > 2.0:
                bx(mid, (lo + hi) / 2, 0.06, 0.05, hi - lo - 2 * f, 0.07, "trim")   # mullion
                panes = [(a0 + f, mid - 0.025), (mid + 0.025, a1 - f)]
            for p0, p1 in panes:
                if rng.random() < 0.3:                     # still whole (round 4, owner: most windows smashed)
                    b.poly([P(p0, lo + f, 0.06), P(p1, lo + f, 0.06), P(p1, hi - f, 0.06), P(p0, hi - f, 0.06)], nrm,
                           "glass", uv_world(1.0))
                else:
                    shards(ctx, p0, p1, lo + f, hi - f, at + out * 0.06, "x" if ns else "z", rng)
        elif kind == "big_door" and BUILDING_NAME[0] in SLIDING_DOORS:
            # Farm buildings (World art 0.17): solid sliding doors run back along the wall, a frame round the opening.
            mat, trim = SLIDING_DOORS[BUILDING_NAME[0]]
            for a in (a0 + 0.06, a1 - 0.06):
                bx(a, (lo + hi) / 2, 0.06, 0.12, hi - lo, 0.1, trim)
            bx(mid, hi - 0.06, 0.06, w, 0.12, 0.1, trim)
            for sg in (-1, 1):
                fate = rng.random()
                if fate < 0.2:
                    continue                                                        # gone
                c = P(mid + sg * (w * 0.75 + 0.06), (hi - lo) / 2 + lo, 0.2)
                b.box(c, ((w / 2, hi - lo - 0.05, 0.08) if ns else (0.08, hi - lo - 0.05, w / 2)),
                      style=lambda n, m, q: (mat, uv_world(2.0)) if (abs(n[2]) > 0.7 if ns else abs(n[0]) > 0.7) else ("trim_dark", uv_world(1.0)))
                for y in (lo + 0.4, hi - 0.4):                                       # the braces
                    cb = P(mid + sg * (w * 0.75 + 0.06), y, 0.25)
                    b.box(cb, ((w / 2, 0.14, 0.03) if ns else (0.03, 0.14, w / 2)), style=_nb(trim))
            continue
        elif kind in ("door", "big_door"):
            for a in (a0 + 0.045, a1 - 0.045):                                    # door frame (off the jambs)
                bx(a, (lo + hi) / 2, 0.0, 0.08, hi - lo, 0.32, "trim_dark")
            bx(mid, hi - 0.04, 0.0, w - 0.17, 0.08, 0.32, "trim_dark")              # (between the posts)
            if BUILDING_NAME[0] in ROLLER_DOORS and w > 3.0:
                continue
            leaves = 2 if w > 1.5 else 1
            lw = w / leaves
            mat = ENTRANCE_DOOR.get(BUILDING_NAME[0], "trim")
            for k in range(leaves):
                fate = rng.random()
                if fate < 0.3:
                    continue                                                        # torn off and gone
                hinge = a0 + 0.08 if k == 0 else a1 - 0.08
                sgn = 1 if k == 0 else -1
                hh = hi - lo - 0.1
                if fate < 0.6:                                                     # lying on the ground outside
                    ang = rng.uniform(-12, 12)               # (round 4: clear of the frame and step)
                    c = P(hinge + sgn * lw * 0.5, lo + 0.03 + k * 0.012, hh / 2 + 0.45 + rng.uniform(0, 0.4))
                    yaw = (0 if ns else 90) + ang
                    _door_leaf(b, c, lw - 0.12, hh, yaw, 90, mat, rng)
                else:                                                              # hanging open, off a hinge
                    th = math.radians(rng.uniform(70, 110))
                    if BUILDING_NAME[0] in HOUSES:         # (round 11, owner: a leaf across the hall read as a rail
                        th = math.radians(rng.uniform(165, 172))   # blocking the way in) folded back to the wall
                    u = (1.0, 0.0) if ns else (0.0, 1.0)                           # along the wall (x, z)
                    v = (0.0, float(out)) if ns else (float(out), 0.0)             # outwards
                    dx = sgn * math.cos(th) * u[0] - math.sin(th) * v[0]
                    dz = sgn * math.cos(th) * u[1] - math.sin(th) * v[1]
                    hp = P(hinge + sgn * 0.05, lo + hh / 2 + 0.02, -0.22)   # (inside the frame, not through it)
                    c = (hp[0] + dx * lw * 0.5, hp[1], hp[2] + dz * lw * 0.5)
                    _door_leaf(b, c, lw - 0.12, hh, math.degrees(math.atan2(-dz, dx)), 0, mat, rng, upright=True)


def paint_rubble_core(rng):
    """Broken concrete (round 8, owner: rubble more 3D/textured): grey with pale aggregate and dark pits."""
    c = Canvas(64, 64, "steel")
    c.noise(0, 0, 64, 64, ["steel_light", "concrete"], 0.18, rng)
    c.noise(0, 0, 64, 64, ["iron", "iron_dark"], 0.1, rng)
    c.noise(0, 0, 64, 64, ["sand"], 0.04, rng)
    c.blotch(["iron"], 5, rng, size=(2, 4))
    return c


KIT["rubble_core"] = paint_rubble_core


def _rubble_mats():
    cfg = SHELLS.get(BUILDING_NAME[0], {})
    ext = cfg.get("ext", "ext_block")      # (round 11, owner: rubble should match the building, not red brick)
    if callable(ext):
        ext = ext((0.0, 0.5, 0.0))
    return (ext, ext, "rubble_core")


def rubble_chunk(b, at, size, rng, mats, yaw=None):
    """A broken lump (round 8, owner: "more 3D"): the main piece shows the wall's skin on top when it's a bit of wall,
    broken concrete on the snapped sides; bigger ones get smaller lumps stuck to them (a ragged outline) and some a
    bent rebar poking out. Bricks (small, brick material) stay single boxes."""
    yaw = rng.uniform(0, 90) if yaw is None else yaw
    pitch = rng.uniform(-20, 20)
    skin = rng.choice(mats)
    if skin == "brick" or max(size) < 0.3:
        b.box(at, size, yaw=yaw, pitch=pitch, style=no_bottom(skin, 1.0))
        return
    b.box(at, size, yaw=yaw, pitch=pitch, style=lambda n, m, q: None if n[1] < -0.7 else
          ((skin, uv_world(2.0)) if n[1] > 0.7 else ("rubble_core", uv_world(1.0))))
    if max(size[0], size[2]) < 0.5:
        return
    for _ in range(rng.randint(2, 3)):                                  # lumps stuck on: a ragged outline
        o = rot((rng.uniform(-0.4, 0.4) * size[0], 0, rng.uniform(-0.4, 0.4) * size[2]), yaw, 0)
        lw, lh, ld = size[0] * rng.uniform(0.3, 0.5), size[1] * rng.uniform(0.4, 0.8), size[2] * rng.uniform(0.3, 0.5)
        b.box((at[0] + o[0], at[1] + size[1] * rng.uniform(0.1, 0.4), at[2] + o[2]), (lw, lh, ld),
              yaw=yaw + rng.uniform(-35, 35), pitch=rng.uniform(-25, 25), style=no_bottom("rubble_core", 1.0))
    if rng.random() < 0.5:                                              # rebar
        o = rot((size[0] * 0.45, 0, rng.uniform(-0.3, 0.3) * size[2]), yaw, 0)
        b.box((at[0] + o[0], at[1] + size[1] * 0.2, at[2] + o[2]), (0.5, 0.025, 0.025), yaw=yaw + rng.uniform(-30, 30),
              pitch=rng.uniform(10, 35), style=no_bottom("trim_dark", 1.0))


def prop_rubble(ctx, c, s, k):
    """A chunk of blown-out wall lying on the ground (round 4: drawn in the building's own materials)."""
    rng = random.Random(f"rubble{c}")
    mats = _rubble_mats()
    yaw = ctx.row.get("yaw", 0.0)
    rubble_chunk(ctx.b, (c[0], c[1] - s[1] * 0.15, c[2]), (s[0] * 0.8, s[1] * 0.7, s[2] * 0.8), rng, mats, yaw)
    for _ in range(3):
        o = rot((rng.uniform(-0.5, 0.5) * s[0], 0, rng.uniform(-0.5, 0.5) * s[2]), yaw, 0)
        rubble_chunk(ctx.b, (c[0] + o[0], c[1] - s[1] / 2 + 0.06, c[2] + o[2]), (0.22, 0.1, 0.12), rng, mats)


def prop_rubble_heap(ctx, c, s, k):
    """A heap of wall rubble (the box is its collision, cover): big slabs at the bottom, chunks and bricks on top."""
    rng = random.Random(f"heap{c}")
    mats = _rubble_mats()
    yaw = ctx.row.get("yaw", 0.0)
    y0 = c[1] - s[1] / 2
    for layer, (n, frac_h, spread) in enumerate(((5, 0.45, 0.42), (4, 0.35, 0.3), (3, 0.3, 0.18))):
        for _ in range(n):
            o = rot((rng.uniform(-spread, spread) * s[0], 0, rng.uniform(-spread, spread) * s[2]), yaw, 0)
            h = s[1] * frac_h
            y = y0 + h / 2 + layer * s[1] * 0.28
            rubble_chunk(ctx.b, (c[0] + o[0], y, c[2] + o[2]),
                         (rng.uniform(0.35, 0.7) * s[0] * (1 - layer * 0.25), h, rng.uniform(0.35, 0.7) * s[2] * (1 - layer * 0.25)),
                         rng, mats)
    for _ in range(10):                                                    # loose bricks round the foot
        o = rot((rng.uniform(-0.65, 0.65) * s[0], 0, rng.uniform(-0.65, 0.65) * s[2]), yaw, 0)
        rubble_chunk(ctx.b, (c[0] + o[0], y0 + 0.04, c[2] + o[2]), (0.22, 0.07, 0.11), rng, (mats[0], "rubble_core"))


PROPS_EXTRA = {"rubble": prop_rubble, "rubble_heap": prop_rubble_heap}


def dress_blast(ctx, o, P, out, ns, a0, a1, lo, hi, rng):
    """A blast hole (round 4, owner: "make this wall that's broken proper"): jagged lumps of wall lining the sides and
    top of the hole (outside skin outside, plaster in, broken brick where it snapped), scorch round it, and the wall
    that came in lying in the room."""
    b = ctx.b
    cfg = SHELLS.get(BUILDING_NAME[0], {})
    ext = cfg.get("ext", "ext_block")
    if callable(ext):                                                   # (a skin by height: the hole's storey's)
        ext = ext(P(0.5 * (a0 + a1), 0.5 * (lo + hi), 0.3))
    inner = cfg.get("inner")
    t = 0.28                                                            # just under the wall's thickness

    def lump(a, y, la, h, stick):
        """A broken piece at `a` along the wall, sticking `stick` into the hole."""
        mid_in = P(a, y, -0.3)
        int_mat = inner(mid_in) if inner else "int_wall"

        def st(n, m, q):
            if ns:
                face_out = n[2] * out > 0.7
                face_in = n[2] * out < -0.7
            else:
                face_out = n[0] * out > 0.7
                face_in = n[0] * out < -0.7
            if face_out:
                return (ext, uv_world())
            if face_in:
                return (int_mat, uv_world())
            return (cfg.get("core", "brick"), uv_world(1.0))
        c = P(a, y, 0.0)
        b.box(c, (la, h, t) if ns else (t, h, la), style=st)
    # Sides: a stack of lumps whose stick-out changes, so the edge is ragged.
    for edge, sgn in ((a0, 1), (a1, -1)):
        y = lo
        while y < hi - 0.05:
            h = min(rng.uniform(0.3, 0.6), hi - y)
            stick = rng.uniform(0.06, 0.3)
            lump(edge + sgn * (stick / 2 - 0.04), y + h / 2, stick + 0.08, h, stick)
            y += h
    # Top: lumps hanging down from the lintel.
    a = a0
    while a < a1 - 0.05:
        la = min(rng.uniform(0.3, 0.7), a1 - a)
        drop = rng.uniform(0.1, 0.55)
        lump(a + la / 2, hi - drop / 2 + 0.04, la, drop + 0.08, 0)
        a += la
    # A bent bar of rebar poking out of the top.
    for _ in range(2):
        ax = rng.uniform(a0 + 0.4, a1 - 0.4)
        b.box(P(ax, hi - 0.6, rng.uniform(-0.05, 0.05)), (0.025, 0.7, 0.025) if ns else (0.025, 0.7, 0.025),
              yaw=rng.uniform(0, 90), pitch=rng.uniform(-30, 30), style=no_bottom("trim_dark", 1.0))
    # Scorch round the hole, outside and in.
    for d, nrm_out in ((0.165, out), (-0.165, -out)):
        for sgn in (-1, 1):
            e = a0 - 0.75 if sgn < 0 else a1 - 0.05
            pts = [P(e, lo + 0.2, d), P(e + 0.8, lo + 0.2, d), P(e + 0.8, hi - 0.1, d), P(e, hi - 0.1, d)]
            b.poly(pts, (0, 0, nrm_out) if ns else (nrm_out, 0, 0), "graffiti", ctx.d("blast_soot", sgn < 0))
    # The wall that came in: slabs and chunks on the floor inside, a dust spread.
    mats = (ext, ext, "concrete")
    for _ in range(9):
        a = rng.uniform(a0 + 0.2, a1 - 0.2)
        rubble_chunk(b, P(a, lo + 0.06, -rng.uniform(0.5, 2.0)), (rng.uniform(0.2, 0.5), 0.12, rng.uniform(0.15, 0.4)),
                     rng, mats)
    for _ in range(14):
        a = rng.uniform(a0 - 0.3, a1 + 0.3)
        rubble_chunk(b, P(a, lo + 0.035, -rng.uniform(0.3, 2.6)), (0.2, 0.06, 0.1), rng, (ext, "rubble_core"))
    p0, p1 = P(a0 + 0.1, lo + 0.012, -0.25), P(a1 - 0.1, lo + 0.012, -2.2)
    b.box(((p0[0] + p1[0]) / 2, lo + 0.012, (p0[2] + p1[2]) / 2), (abs(p1[0] - p0[0]), 0.02, abs(p1[2] - p0[2])),
          style=no_bottom("concrete", 2.0))


def _door_leaf(b, c, w, h, yaw, tilt, mat, rng, upright=False):
    """A broken door leaf centred at c: frame of `mat`, its glass smashed out (a few shards left)."""
    lay = not upright
    # (grocery z-fight pass: the rails fit between the stiles; overlapping corners flickered)
    parts = [((0, h / 2 - 0.05, 0), (w - 0.2, 0.1, 0.045)), ((0, -h / 2 + 0.12, 0), (w - 0.2, 0.24, 0.045)),
             ((-w / 2 + 0.05, 0, 0), (0.1, h, 0.045)), ((w / 2 - 0.05, 0, 0), (0.1, h, 0.045)),
             ((0, -h * 0.05, 0), (w - 0.2, 0.06, 0.04))]
    for off, size in parts:
        if lay:
            # lying flat: local y goes along the ground (pitch -90 turns the door's up onto -z then yaw)
            o = rot(off, yaw, -90)
            p = (c[0] + o[0], c[1] + 0.025, c[2] + o[2])
            b.box(p, size, yaw=yaw, pitch=-90, style=no_bottom(mat, 1.0))
        else:
            o = rot(off, yaw, 0)
            p = (c[0] + o[0], c[1] + o[1], c[2] + o[2])
            b.box(p, size, yaw=yaw, style=no_bottom(mat, 1.0))


def water_heater(b, x, y, z):
    """A tank water heater (round 5, owner: the plain box in the gas station corner): a round-ish white tank on a
    stand, a domed top, the pipes up to the ceiling with red and blue taps, a thermostat box and a drain tap."""
    b.box((x, y + 0.08, z), (0.5, 0.16, 0.5), style=no_bottom("trim_dark", 1.0))                       # stand
    for yaw in (0, 45):                                                                       # eight-sided tank
        b.box((x, y + 0.85, z), (0.52, 1.4, 0.52), yaw=yaw, style=no_bottom("bone", 1.0))
    for yaw in (0, 45):                                                                       # domed top
        b.box((x, y + 1.6, z), (0.4, 0.1, 0.4), yaw=yaw, style=no_bottom("bone", 1.0))
    for k, (dx, tap) in enumerate(((-0.1, "red"), (0.1, "blue"))):                             # hot and cold pipes
        b.box((x + dx, y + 2.3, z), (0.05, 1.3, 0.05), style=no_bottom("trim", 1.0))
        b.box((x + dx, y + 1.95, z + 0.05), (0.1, 0.03, 0.03), yaw=30 * (k * 2 - 1), style=no_bottom(tap, 1.0))
    b.box((x, y + 0.45, z + 0.3), (0.16, 0.2, 0.06), style=no_bottom("steel_light", 1.0))      # thermostat
    b.box((x, y + 0.47, z + 0.335), (0.06, 0.06, 0.01), style=no_bottom("red", 1.0))           # its dial
    b.box((x - 0.15, y + 0.25, z + 0.3), (0.04, 0.04, 0.1), style=no_bottom("trim", 1.0))      # drain tap
    b.box((x - 0.27, y + 1.2, z), (0.03, 0.03, 0.03), style=no_bottom("trim", 1.0))            # relief valve
    b.box((x - 0.31, y + 0.65, z), (0.025, 1.1, 0.025), style=no_bottom("trim", 1.0))          # and its pipe


def change_machine(b, x, z):
    """A laundromat change machine against a wall, facing -x (round 6, owner: it was a plain grey box): a steel
    cabinet on a plinth, a lit display, a bill slot, a coin cup, a red CHANGE strip and a lock."""
    nb = lambda m: no_bottom(m, 1.0)
    b.box((x, 0.05, z), (0.42, 0.1, 0.52), style=nb("trim_dark"))                           # plinth
    b.box((x, 0.75, z), (0.4, 1.3, 0.5), style=nb("steel_light"))                           # cabinet
    f = x - 0.2                                                                              # the front face
    b.box((f - 0.015, 0.75, z), (0.03, 1.2, 0.42), style=nb("trim"))                        # door panel
    b.box((f - 0.035, 1.28, z), (0.01, 0.12, 0.3), style=nb("red"))                         # CHANGE strip
    b.box((f - 0.035, 1.1, z + 0.08), (0.01, 0.08, 0.16), style=nb("black"))                # display
    b.box((f - 0.04, 1.1, z + 0.08), (0.005, 0.03, 0.1), style=nb("green"))                 # its digits
    b.box((f - 0.04, 0.95, z + 0.08), (0.02, 0.025, 0.18), style=nb("black"))               # bill slot
    b.box((f - 0.035, 0.95, z - 0.12), (0.01, 0.06, 0.06), style=nb("yellow"))              # button
    b.box((f - 0.08, 0.38, z), (0.1, 0.02, 0.2), style=nb("trim_dark"))                     # coin cup floor
    for dz in (-0.1, 0.1):
        b.box((f - 0.08, 0.44, z + dz), (0.1, 0.12, 0.015), style=nb("trim_dark"))          # its sides
    b.box((f - 0.13, 0.43, z), (0.01, 0.1, 0.2), style=nb("trim_dark"))                     # its lip
    b.box((f - 0.035, 0.7, z - 0.15), (0.01, 0.05, 0.05), style=nb("steel_light"))          # lock


def floor_lamp(b, x, y, z, rng):
    """A standard lamp (round 4, owner: it read as a pole with a box): a stepped round-ish foot, a thin pole with a
    joint, a flared fabric shade (three tiers) with the bulb showing under it, a pull chain."""
    for k, (w, h) in enumerate(((0.32, 0.03), (0.24, 0.03), (0.1, 0.04))):            # weighted foot
        b.box((x, y + 0.015 + k * 0.03, z), (w, h, w), yaw=45 * (k % 2), style=no_bottom("trim_dark", 1.0))
    b.box((x, y + 0.75, z), (0.03, 1.3, 0.03), style=no_bottom("trim", 1.0))              # pole
    b.box((x, y + 0.75, z), (0.05, 0.05, 0.05), style=no_bottom("trim", 1.0))      # joint
    tilt = rng.uniform(-6, 6)                                                             # knocked a bit askew
    for k, (w, h) in enumerate(((0.46, 0.12), (0.38, 0.1), (0.3, 0.08))):                 # the shade, flaring down
        b.box((x, y + 1.42 + k * 0.1, z), (w, h, w), yaw=0, pitch=tilt, style=lambda n, m, q: (
            ("bone", uv_world(1.0)) if abs(n[1]) < 0.7 else ("cardboard", uv_world(1.0))))
    b.box((x, y + 1.36, z), (0.08, 0.06, 0.08), style=no_bottom("yellow", 1.0))           # bulb
    b.box((x + 0.1, y + 1.27, z), (0.008, 0.16, 0.008), style=no_bottom("trim", 1.0))   # pull chain


def wet_floor_sign(ctx, x, y, z, yaw):
    """A-frame caution sign: two yellow boards hinged at the top, the warning on both outsides."""
    b = ctx.b
    cy, sy = math.cos(math.radians(yaw)), math.sin(math.radians(yaw))

    def P(px, py, pz):                     # local (x across, y up, z the way the legs splay) -> model
        return (x + px * cy + pz * sy, y + py, z - px * sy + pz * cy)
    w, h, foot, head = 0.15, 0.62, 0.15, 0.015
    for sz in (-1, 1):
        lo, hi = sz * foot, sz * head
        ln = (0.0, -sz * (hi - lo), sz * h)                       # outward (and a little up), local
        nrm = norm((ln[0] * cy + ln[2] * sy, ln[1], -ln[0] * sy + ln[2] * cy))
        quad = [P(-w, 0.0, lo), P(w, 0.0, lo), P(w, h, hi), P(-w, h, hi)]
        b.poly(quad, nrm, "decals", ctx.d("wet"))
        b.poly(quad, v_scale(nrm, -1.0), "yellow", uv_world(1.0))
    b.box(P(0, h + 0.015, 0), (0.32, 0.03, 0.05), yaw=yaw, style=no_bottom("yellow", 1.0))    # hinge cap


