LOCKER_PAINT = {}   # the lockers' paint (sides, open doors) where it isn't the school's red


def prop_hall_lockers(ctx, c, s):
    """A row of school lockers, 0.5 m each. Round 3 (owner): most shut, some really open (the door swung on its
    hinge, a dark hollow inside with a few books, a bag or papers), a few dented or with the door torn off."""
    b, rng = ctx.b, random.Random(f"lockers{c}")
    front = _front_into(c, 2)
    f = 1 if front == "+z" else -1
    y0, y1 = c[1] - s[1] / 2, c[1] + s[1] / 2
    x0, x1 = c[0] - s[0] / 2, c[0] + s[0] / 2
    zf, zb = c[2] + f * s[2] / 2, c[2] - f * s[2] / 2
    b.box(c, s, style=lambda n, m, q: None if side_of(n) in (front, "-y") else (LOCKER_PAINT.get(BUILDING_NAME[0], "red"), uv_world()))
    n = max(1, round(s[0] / 0.5))
    w = s[0] / n
    fates = ["shut"] * n
    slots = list(range(n))
    rng.shuffle(slots)
    for k, fate in zip(slots, ["open", "open", rng.choice(("open", "gone", "dent")), rng.choice(("gone", "dent", "shut"))]):
        fates[k] = fate
    for k in range(n):
        xa, xb = x0 + k * w, x0 + (k + 1) * w
        fate = fates[k]
        if fate in ("shut", "dent"):
            r = ctx.decals.regions["locker" if fate == "shut" else "locker_dent"]
            b.poly([(xa, y0, zf), (xb, y0, zf), (xb, y1, zf), (xa, y1, zf)], (0, 0, f), "decals", uv_fit(r))
            continue
        # The hollow: a dark back, sides, roof and floor facing in, a hat shelf.
        e = 0.015
        zi = zb + f * 0.02
        b.poly([(xa, y0, zi), (xb, y0, zi), (xb, y1, zi), (xa, y1, zi)], (0, 0, f), "black", uv_world(1.0))
        for x, nx in ((xa + e, 1), (xb - e, -1)):
            b.poly([(x, y0, zi), (x, y0, zf), (x, y1, zf), (x, y1, zi)], (nx, 0, 0), "trim_dark", uv_world(1.0))
        for y, ny in ((y0 + 0.1, 1), (y1 - 0.05, -1)):
            b.poly([(xa, y, zi), (xb, y, zi), (xb, y, zf), (xa, y, zf)], (0, ny, 0), "trim_dark", uv_world(1.0))
        shelf = y1 - 0.42
        b.box(((xa + xb) / 2, shelf, (zi + zf) / 2), (w - 2 * e, 0.02, abs(zf - zi)), style=no_bottom("trim", 1.0))
        # What's left inside.
        xm, zm = (xa + xb) / 2, (zi + zf) / 2
        if rng.random() < 0.6:                                               # a stack of books on the floor
            for t in range(rng.randrange(1, 4)):
                b.box((xm + rng.uniform(-0.04, 0.04), y0 + 0.12 + t * 0.045, zm), (0.24, 0.04, 0.17),
                      yaw=rng.uniform(-15, 15), style=no_bottom(rng.choice(ITEM_COLOURS[:6]), 1.0))
        elif rng.random() < 0.7:                                             # a school bag slumped in the corner
            col = rng.choice(("blue", "green", "olive", "red"))
            b.box((xm, y0 + 0.28, zm), (0.3, 0.36, 0.16), yaw=rng.uniform(-10, 10), pitch=-f * 8,
                  style=no_bottom(col, 1.0))
            b.box((xm, y0 + 0.2, zm + f * 0.09), (0.22, 0.16, 0.03), style=no_bottom(col, 1.0))   # pocket
        if rng.random() < 0.6:                                               # papers on the shelf
            b.box((xm, shelf + 0.02, zm), (0.21, 0.01, 0.3), yaw=rng.uniform(-20, 20), style=no_bottom("bone", 1.0))
        if rng.random() < 0.5:
            b.box((xa + 0.08, shelf + 0.13, zm), (0.04, 0.22, 0.17), style=no_bottom(rng.choice(ITEM_COLOURS[:6]), 1.0))
        hh = y1 - y0 - 0.06
        if fate == "open":                                                   # the door swung out on its hinge
            sgn = rng.choice((1, -1))
            hinge = xa if sgn > 0 else xb
            th = math.radians(rng.uniform(95, 130))
            dx, dz = sgn * math.cos(th), f * math.sin(th)
            out = (-f * sgn * dz, f * sgn * dx)                              # the face that showed to the hall
            centre = (hinge + dx * w / 2, y0 + 0.03 + hh / 2, zf + dz * w / 2)
            r = ctx.decals.regions["locker"]

            def leaf_style(nrm, m, q, out=out, r=r):
                if nrm[1] < -0.7:
                    return None
                if nrm[0] * out[0] + nrm[2] * out[1] > 0.7:
                    return ("decals", uv_fit(r))
                return (LOCKER_PAINT.get(BUILDING_NAME[0], "red"), uv_world(1.0))   # painted both sides
            b.box(centre, (w - 0.02, hh, 0.02), yaw=math.degrees(math.atan2(-dz, dx)), style=leaf_style)
        elif rng.random() < 0.6:                                             # torn off, lying in the hall
            b.box((xa + w / 2 + rng.uniform(-0.3, 0.3), y0 + 0.012, zf + f * rng.uniform(0.5, 0.8)), (w - 0.02, 0.02, hh),
                  yaw=rng.uniform(70, 110), style=no_bottom(LOCKER_PAINT.get(BUILDING_NAME[0], "red"), 1.0))


def prop_trophy_case(ctx, c, s):
    """Trophy case (refine pass: 3D): wooden cabinet below, a glass case above with glass shelves, blue felt at the
    back and real little trophies (cups with handles, figure trophies, plaques)."""
    b, rng = ctx.b, random.Random(f"trophy{c}")
    face = 1 if _front_into(c, 2) == "+z" else -1
    x0, x1 = c[0] - s[0] / 2, c[0] + s[0] / 2
    y0, y1 = c[1] - s[1] / 2, c[1] + s[1] / 2
    zb, zf = c[2] - face * s[2] / 2, c[2] + face * s[2] / 2           # back and front planes
    mid_z = c[2]
    base_h = 0.62
    b.box((c[0], y0 + base_h / 2, mid_z), (s[0], base_h, s[2]), style=no_bottom("wood", 1.0))        # cabinet
    for k in range(2):                                                                                # its doors
        dx = x0 + s[0] * (k + 0.5) / 2
        b.box((dx, y0 + 0.33, zf + face * 0.006), (s[0] / 2 - 0.12, 0.42, 0.012), style=no_bottom("trim_dark", 1.0))
        b.box((dx + (0.15 if k == 0 else -0.15) * 1, y0 + 0.36, zf + face * 0.018), (0.03, 0.12, 0.02),
              style=no_bottom("yellow", 1.0))
    b.box((c[0], (y0 + base_h + y1) / 2, zb + face * 0.015), (s[0], y1 - y0 - base_h, 0.03), style=no_bottom("blue", 1.0))
    for x in (x0 + 0.03, x1 - 0.03, c[0]):                                                            # frame posts
        b.box((x, (y0 + base_h + y1) / 2, zf - face * 0.025), (0.06 if x != c[0] else 0.04, y1 - y0 - base_h, 0.05),
              style=no_bottom("wood", 1.0))
    b.box((c[0], y1 - 0.04, mid_z), (s[0], 0.08, s[2]), style=lambda n, m, q: ("wood", uv_world(1.0)))  # top
    shelves = (y0 + base_h, y0 + base_h + 0.42, y0 + base_h + 0.82)
    depth = s[2] - 0.1
    for k, y in enumerate(shelves):
        if k:
            b.box((c[0], y - 0.01, mid_z), (s[0] - 0.08, 0.02, depth), style=lambda n, m, q: ("glass", uv_world(1.0)))
        # Trophies along the shelf, some gone (looted), a few knocked over.
        x = x0 + 0.16
        while x < x1 - 0.16:
            if rng.random() < 0.8:
                kind = rng.choice(("cup", "cup", "figure", "plaque"))
                metal = rng.choice(("yellow", "yellow", "steel_light"))
                zz = mid_z + face * rng.uniform(-0.04, 0.04)
                trophy(b, x, y, zz, kind, metal, rng.uniform(0.22, 0.34), face)
            x += rng.uniform(0.24, 0.34)
    for k in range(2):                                                                                # glass doors
        a, e = (x0 + 0.06, c[0] - 0.02) if k == 0 else (c[0] + 0.02, x1 - 0.06)
        shards(ctx, a, e, y0 + base_h, y1 - 0.08, zf, "x", rng)                 # smashed in


def trophy(b, x, y, z, kind, metal, h, face):
    """One small trophy standing at (x, y, z), `h` tall: a dark base, then a cup with handles, a little figure on a
    column, or a plaque (wooden board with a metal plate) facing out."""
    b.group = ("item", len(b.faces))
    nb = lambda mat: no_bottom(mat, 1.0)
    if kind == "plaque":
        b.box((x, y + h * 0.4, z - face * 0.04), (0.16, h * 0.8, 0.03), pitch=-8 * face, style=nb("wood"))
        b.box((x, y + h * 0.42, z - face * 0.022), (0.11, h * 0.4, 0.008), pitch=-8 * face, style=nb(metal))
        b.group = None
        return
    b.box((x, y + 0.03, z), (0.1, 0.06, 0.1), style=nb("black"))                                      # base
    b.box((x, y + 0.075, z), (0.07, 0.03, 0.07), style=nb("black"))
    if kind == "cup":
        b.box((x, y + 0.09 + h * 0.15, z), (0.025, h * 0.3, 0.025), style=nb(metal))                   # stem
        b.box((x, y + 0.09 + h * 0.3 + 0.01, z), (0.06, 0.02, 0.06), style=nb(metal))
        cup_h = h * 0.45
        b.box((x, y + 0.09 + h * 0.3 + 0.02 + cup_h / 2, z), (0.1, cup_h, 0.1), style=nb(metal))       # cup
        for sx in (-1, 1):                                                                             # handles
            b.box((x + sx * 0.065, y + 0.09 + h * 0.3 + 0.02 + cup_h * 0.6, z), (0.03, cup_h * 0.5, 0.015), style=nb(metal))
    else:
        b.box((x, y + 0.09 + h * 0.25, z), (0.045, h * 0.5, 0.045), style=nb("bone"))                 # column
        fy = y + 0.09 + h * 0.5
        b.box((x, fy + h * 0.12, z), (0.04, h * 0.24, 0.03), style=nb(metal))                          # body
        b.box((x, fy + h * 0.27, z), (0.03, 0.03, 0.03), style=nb(metal))                              # head
        b.box((x + 0.03, fy + h * 0.2, z), (0.06, 0.012, 0.012), yaw=0, pitch=0, style=nb(metal))      # arm up
    b.group = None


