# The pharmacy (map 90-105 x 72-84, model origin map (97.5, 78)): shop floor east (door south), dispensary west
# (its north wall blown out). Local x < 0 is the dispensary.
def paint_int_clinic(rng):
    """Clean white walls with a mint stripe at 1 m (grubby now)."""
    c = Canvas(64, 64, "bone")
    c.rect(0, 15, 64, 18, "extract_green")
    c.rect(0, 0, 64, 2, "steel")
    c.blotch(["concrete"], 8, rng, area=(0, 18, 64, 64), size=(2, 5))
    return c


def paint_floor_pharm(rng):
    """Big white tiles (1 m), the odd mint one, scuffed."""
    c = Canvas(64, 64, "bone")
    for ty in range(4):
        for tx in range(4):
            if rng.random() < 0.15:
                c.rect(tx * 16 + 1, ty * 16 + 1, tx * 16 + 16, ty * 16 + 16, "olive_light")
    for i in range(0, 64, 16):
        c.rect(i, 0, i + 1, 64, "steel_light")
        c.rect(0, i, 64, i + 1, "steel_light")
    c.blotch(["concrete", "sand"], 6, rng, size=(2, 5))
    return c


def paint_clinic_panel(rng):
    """Outside of the pharmacy (round 8, owner: "make it look like a pharmacy"): big smooth cladding panels, 1 x 2 m,
    cool pale grey-green with dark seams and rivets, the odd panel a shade off (replaced), grime run down from the
    joints, one panel cracked. Mid-light so the sunny side is bright, not blinding."""
    c = Canvas(64, 64, "clinic")
    for py in range(2):
        for px in range(4):
            x0, y0 = px * 16, py * 32
            if rng.random() < 0.3:
                c.rect(x0 + 1, y0 + 1, x0 + 16, y0 + 32, "clinic_light")
            c.rect(x0, y0, x0 + 1, y0 + 32, "clinic_seam")                 # seams
            c.rect(x0, y0, x0 + 16, y0 + 1, "clinic_seam")
            for rx, ry in ((2, 3), (14, 3), (2, 29), (14, 29)):              # rivets
                c.put(x0 + rx, y0 + ry, "steel")
            for _ in range(2):                                              # grime from the joint above
                gx = x0 + rng.randrange(2, 15)
                for gy in range(y0 + rng.randrange(16, 26), y0 + 31):
                    if rng.random() < 0.6:
                        c.put(gx, gy, "steel_light" if rng.random() < 0.5 else "clinic_seam")
    x, y = rng.randrange(20, 44), rng.randrange(36, 56)                      # a crack across one panel
    for _ in range(12):
        c.put(x % 64, y % 64, "clinic_seam")
        x += 1
        y += rng.choice((-1, 0, 1))
    return c


KIT.update({"clinic_panel": paint_clinic_panel, "int_clinic": paint_int_clinic, "floor_pharm": paint_floor_pharm, "mint": paint_flat("extract_green")})


def paint_grey_brick(rng):
    """Outside of the pharmacy (round 9, owner's pick D): pale grey brick, 0.5 x 0.25 m in stretcher bond, a few
    bricks a shade off, soot patches and rain grime run down from the courses. Mid-light for the sun."""
    c = Canvas(64, 64, "gbrick_mortar")
    for row in range(16):
        off = 4 if row % 2 else 0
        for k in range(8):
            col = rng.choice(("gbrick", "gbrick", "gbrick", "gbrick_dark", "gbrick_light"))
            for x in range(k * 8 + off + 1, k * 8 + off + 8):
                c.rect(x % 64, row * 4 + 1, x % 64 + 1, row * 4 + 4, col)
    c.blotch(["gbrick_dark"], 6, rng, size=(2, 5))
    for _ in range(5):                                                   # rain grime down the wall
        gx = rng.randrange(64)
        for gy in range(rng.randrange(0, 30), rng.randrange(36, 64)):
            if rng.random() < 0.45:
                c.put(gx, gy, "gbrick_mortar")
    c.blotch(["iron"], 2, rng, size=(2, 4))                              # soot
    return c


def paint_sandstone(rng):
    """Outside of the shops (round 9, owner's pick D): sandstone blocks, 1 x 0.5 m in a running bond, each block its
    own shade with speckle, weathered joints, a few chipped corners and soot. Mid-tone for the sun."""
    c = Canvas(64, 64, "sandst_joint")
    for row in range(8):
        off = 8 if row % 2 else 0
        for k in range(5):
            col = rng.choice(("sandst", "sandst_dark", "sandst_light"))
            for x in range(k * 16 + off + 1, k * 16 + off + 16):
                c.rect(x % 64, row * 8 + 1, x % 64 + 1, row * 8 + 8, col)
    c.noise(0, 0, 64, 64, ["sandst_dark", "sandst_light"], 0.06, rng)
    for _ in range(5):                                                   # chipped block corners
        x, y = rng.randrange(0, 64, 16) + 1, rng.randrange(0, 64, 8) + 1
        c.rect(x, y, x + 2, y + 2, "sandst_joint")
    c.blotch(["iron"], 3, rng, size=(2, 4))
    return c


KIT.update({"grey_brick": paint_grey_brick, "sandstone": paint_sandstone})


def pharmacy_decals(rng):
    a = Atlas(512)

    def sign(c):          # 6 x 0.8 m
        c.rect(0, 0, c.w, c.h, "bone")
        c.frame(0, 0, c.w, c.h, "green_dark")
        c.rect(4, 4, 22, 22, "green_dark")
        c.rect(11, 6, 15, 20, "bone")
        c.rect(6, 11, 20, 15, "bone")
        w = Canvas.text_width("PHARMACY", 3)
        c.ctext(28, c.w, 5, "PHARMACY", "green_dark", 3)
        c.blotch(["concrete"], 4, rng, area=(2, 2, c.w - 2, c.h - 2), size=(2, 4))

    def cross(c):         # 1 x 1 m lightbox
        c.rect(0, 0, c.w, c.h, "iron_dark")
        c.rect(2, 2, c.w - 2, c.h - 2, "bone")
        c.rect(c.w // 2 - 4, 5, c.w // 2 + 4, c.h - 5, "extract_green")
        c.rect(5, c.h // 2 - 4, c.w - 5, c.h // 2 + 4, "extract_green")
        c.rect(c.w // 2 - 4, 5, c.w // 2 + 4, 8, "green_dark")

    def meds(c):          # 1.2 x 1.6 m of shelf, part looted
        c.rect(0, 0, c.w, c.h, "steel_light")
        for row in range(4):
            y = 2 + row * 12
            c.rect(0, y - 2, c.w, y, "steel")
            x = 1
            while x < c.w - 3:
                w = rng.choice((3, 4, 5))
                if rng.random() < 0.6:
                    col = rng.choice(("bone", "red", "sky_blue", "extract_green", "hazard_yellow", "bone"))
                    h = rng.randrange(4, 9)
                    c.rect(x, y, x + w, y + h, col)
                    if h > 5:
                        c.rect(x, y + h - 2, x + w, y + h - 1, "bone" if col != "bone" else "sky_blue")
                x += w + 1

    def drawers(c):       # 0.775 x 2 m: a column of little labelled drawers
        c.rect(0, 0, c.w, c.h, "wood_light")
        for y in range(2, c.h - 2, 7):
            c.frame(1, y, c.w - 1, y + 6, "wood_mid")
            c.rect(c.w // 2 - 3, y + 3, c.w // 2 + 3, y + 5, "bone")
            if rng.random() < 0.25:                               # pulled out, empty
                c.rect(2, y + 1, c.w - 2, y + 5, "black")

    def counter(c):       # 2.4 x 1 m till counter front
        c.rect(0, 0, c.w, c.h, "bone")
        c.rect(0, 0, c.w, 3, "steel")
        c.rect(0, c.h - 10, c.w, c.h - 4, "extract_green")
        w = Canvas.text_width("PAY HERE")
        c.ctext(0, c.w, c.h - 9, "PAY HERE", "bone")
        c.blotch(["concrete"], 4, rng, size=(2, 4))

    def rx(c):            # 2.5 x 0.4 m hanging sign
        c.rect(0, 0, c.w, c.h, "green_dark")
        w = Canvas.text_width("PRESCRIPTIONS")
        c.ctext(0, c.w, 4, "PRESCRIPTIONS", "bone")

    def glasses(c):       # 0.6 x 1.6 m sunglasses stand side
        c.rect(0, 0, c.w, c.h, "steel_light")
        for y in range(6, c.h - 4, 7):
            for x in (2, 10):
                if rng.random() < 0.6:
                    col = rng.choice(("black", "red", "sky_blue", "iron_dark"))
                    c.rect(x, y, x + 3, y + 2, col)
                    c.rect(x + 4, y, x + 7, y + 2, col)
                    c.put(x + 3, y + 1, col)
        c.rect(0, c.h - 4, c.w, c.h, "extract_green")

    def poster(lines, colour, ink):
        def paint(c):     # 0.6 x 0.8 m
            c.rect(0, 0, c.w, c.h, colour)
            c.frame(0, 0, c.w, c.h, ink)
            for k, t in enumerate(lines):
                w = Canvas.text_width(t)
                c.ctext(0, c.w, c.h - 9 - k * 7, t, ink)
        return paint

    def looted(c):        # graffiti
        c.rect(0, 0, c.w, c.h, "clear")
        w = Canvas.text_width("NO MEDS", 3)
        c.ctext(0, c.w, 3, "NO MEDS", "red", 3)
        for _ in range(5):
            x = rng.randrange(3, c.w - 3)
            c.rect(x, 0, x + 1, rng.randrange(2, 4), "red")

    a.add("sign", 192, 26, sign)
    a.add("cross", 32, 32, cross)
    a.add("meds", 38, 51, meds)
    a.add("drawers", 25, 64, drawers)
    a.add("counter", 77, 32, counter)
    a.add("rx", 80, 13, rx)
    a.add("glasses", 19, 51, glasses)
    def poster_flu(c):    # 0.6 x 0.8 m: a syringe and FLU (round 4, owner: drawings, not text that doesn't fit)
        c.rect(0, 0, c.w, c.h, "sky_blue")
        c.frame(0, 0, c.w, c.h, "bone")
        c.ctext(0, c.w, c.h - 9, "FLU", "bone")
        for k in range(10):                                   # the syringe, on a slant
            c.rect(4 + k, 4 + k, 7 + k, 7 + k, "bone")
        c.rect(13, 13, 15, 15, "iron_dark")                   # plunger end
        c.rect(3, 3, 4, 4, "steel_light")                     # needle
        c.rect(6, 6, 9, 9, "red")                             # the dose

    def poster_vit(c):    # 0.6 x 0.8 m: a big capsule
        c.rect(0, 0, c.w, c.h, "hazard_yellow")
        c.frame(0, 0, c.w, c.h, "red")
        for y in range(3, 19):
            for x in range(5, 14):
                dx, dy = x - 9, (y - 10.5) if abs(y - 10.5) > 4 else 0
                if dx * dx + dy * dy <= 16:
                    c.put(x, y, "bone" if y >= 11 else "red")
        c.rect(7, 13, 8, 16, "hazard_yellow")                 # a shine
        c.ctext(0, c.w, 20, "VIT", "red")

    a.add("poster_flu", 19, 26, poster_flu)
    a.add("poster_vit", 19, 26, poster_vit)
    a.add("looted", 96, 22, looted)
    return a


