        _box(b, x + 0.17, y0 + 0.85, z, 0.04, 0.45, 0.34, "bone")
        _box(b, x - 0.12, y0 + 0.72, z, 0.3, 0.03, 0.38, "yellow")                    # tray
        _box(b, c[0] + 0.1, top + 0.1, c[2] - 0.05, 0.16, 0.2, 0.06, "yellow")         # cereal box
