    # ---- inside: pictures on the walls
    def pic(side, at, a0, a1, y0, y1, region, mat="decals"):
        n = {"+x": (1, 0, 0), "-x": (-1, 0, 0), "+z": (0, 0, 1), "-z": (0, 0, -1)}[side]
