    office_mess(ctx, -15.8, -13.0, -6.2, -3.5, 0.0, 8)                    # stair hall
    office_mess(ctx, 13.0, 24.4, -8.5, -0.5, 0.0, 35, boxes=1)            # rates office
    office_mess(ctx, -24.4, -13.0, 0.5, 5.4, 0.0, 15)                     # registry
