    b.box((-9.0, 4.55, -8.82), (0.35, 0.45, 0.02), style=_solid("glass"))
    b.box((-8.6, 3.45, -8.32), (0.3, 0.3, 0.02), style=_nb("bone"))
    b.box((-9.55, 3.25, -8.4), (0.2, 0.5, 0.3), style=_nb("blue"))
