    b.box((c[0], y0 + 1.22, c[2] + 0.02), (0.14, 0.12, 0.34), style=_nb("brass"))                 # body (faces +z)
    b.box((c[0], y0 + 1.3, c[2] + 0.22), (0.08, 0.08, 0.1), style=_nb("brass"))                    # head
    b.box((c[0], y0 + 1.29, c[2] + 0.29), (0.03, 0.03, 0.06), style=_nb("bronze"))                 # beak
