    b.box((c[0], top - 0.02, c[2]), (s[0], 0.04, s[2]), style=_nb("wood_dark"))
    for sz in (-1, 1):
        b.box((c[0], y0 + (s[1] - 0.04) / 2, c[2] + sz * (s[2] / 2 - 0.05)), (s[0] - 0.05, s[1] - 0.04, 0.05),
              style=_nb("wood_dark"))
