# ------------------------------------------------------------------------------------------------ washrooms (0.17)
# Owner (2026-10-16): the town had no washrooms; add them where they fit. Gen `washroom()` closes a corner of a room
# with thin walls and a narrow doorway (too narrow for the AI, so their paths don't change) and marks the inside with
# a "washroom" box: here its walls get tiles and its floor a mosaic (shell_box), and the fittings draw from their own
# boxes (wc_toilet, wc_sink, wc_urinal, wc_bath, wc_partition, wc_door, wc_sign). Every fitting faces the middle of
# the washroom it stands in, so the gen only says where each one goes.
def paint_wc_tile(rng):
    """Washroom walls: small white tiles to 2 m (grout lines, a few cracked or missing), a green trim tile, pale
    paint above. Set from the floor with uv_world's offset (the pattern is 4 m tall)."""
    c = Canvas(64, 64, "bone")
    for y in range(32):
        for x in range(64):
            if x % 4 == 0 or y % 4 == 0:
                c.put(x, y, "concrete")
    c.rect(0, 32, 64, 34, "green_dark")
    c.rect(0, 0, 64, 2, "steel")
    for _ in range(5):                                                  # missing tiles
        x, y = rng.randrange(16) * 4, rng.randrange(1, 8) * 4
        c.rect(x + 1, y + 1, x + 4, y + 4, "plaster")
    for _ in range(3):                                                  # cracks
        x, y = rng.randrange(64), rng.randrange(4, 30)
        for k in range(9):
            c.put((x + k) % 64, min(31, y + (k // 2) * rng.choice((1, -1)) % 3), "steel")
    c.blotch(["sand"], 5, rng, area=(0, 2, 64, 30), size=(2, 4))         # grime
    c.blotch(["concrete"], 6, rng, area=(0, 34, 64, 64), size=(2, 5))
    c.blotch(["rust"], 2, rng, area=(0, 2, 64, 12), size=(1, 3))
    return c


def paint_wc_floor(rng):
    """Washroom floor: little grey and white mosaic squares (1/8 m), a drain-dark patch or two, dirt."""
    c = Canvas(64, 64, "bone")
    for y in range(64):
        for x in range(64):
            if x % 2 == 0 or y % 2 == 0:
                c.put(x, y, "concrete")
            elif rng.random() < 0.3:
                c.put(x, y, "steel_light")
    c.blotch(["sand"], 6, rng, size=(2, 5))
    c.blotch(["iron"], 2, rng, size=(1, 3))
    return c


KIT.update({"wc_tile": paint_wc_tile, "wc_floor": paint_wc_floor})


WC_MATS = {}     # (walls, floor) of the washrooms where tiles don't fit (the log cabin: planks)


def wet_rects(data):
    """(x0, y0, z0, x1, y1, z1) inside each washroom of the building."""
    out = []
    for r in data["boxes"]:
        if r.get("kind") == "washroom":
            (px, py, pz), (sx, sy, sz) = r["pos"], r["size"]
            out.append((px - sx / 2, py - sy / 2, pz - sz / 2, px + sx / 2, py + sy / 2, pz + sz / 2))
    return out


def wet_at(ctx, p):
    """The washroom point p is in, or None."""
    for w in getattr(ctx, "wet", ()):
        if w[0] - 0.01 < p[0] < w[3] + 0.01 and w[1] - 0.01 < p[1] < w[4] and w[2] - 0.01 < p[2] < w[5] + 0.01:
            return w
    return None


def wet_wall_style(ctx, base):
    """Wall faces looking into a washroom take its tiles (set from its floor); the rest as before."""
    def style(n, mid, corners):
        if abs(n[1]) < 0.7:
            w = wet_at(ctx, v_add(mid, v_scale(n, 0.08)))
            if w:
                return (WC_MATS.get(BUILDING_NAME[0], ("wc_tile",))[0], uv_world(TILE_M, (0.0, -w[1] / TILE_M)))
        return base(n, mid, corners)
    return style


def _wc_room(ctx, c):
    """The washroom a fitting at c stands in (its middle), or the fitting's own spot."""
    w = wet_at(ctx, c) or wet_at(ctx, (c[0], c[1] - 0.3, c[2]))
    return ((w[0] + w[3]) / 2, (w[2] + w[5]) / 2) if w else (c[0], c[2] + 1.0)


def _wc_face(ctx, c, s):
    """(fx, fz): the way a fitting faces (along its deep axis, toward the washroom's middle), and its width, depth."""
    mx, mz = _wc_room(ctx, c)
    if s[0] > s[2]:                     # wide along x: against a north/south wall
        return (0, 1 if mz > c[2] else -1), s[0], s[2]
    if s[2] > s[0]:
        return (1 if mx > c[0] else -1, 0), s[2], s[0]
    dx, dz = mx - c[0], mz - c[2]
    return ((1 if dx > 0 else -1, 0) if abs(dx) > abs(dz) else (0, 1 if dz > 0 else -1)), s[0], s[2]


def _wc_put(b, c, f, along, out, y, w, h, d, mat, bottom=False):
    """A box at (along the wall, out from it) in a fitting's own frame: f = its facing, out from its back."""
    ax, az = -f[1], f[0]
    x = c[0] + ax * along + f[0] * out
    z = c[2] + az * along + f[1] * out
    size = (w, h, d) if f[0] == 0 else (d, h, w)
    b.box((x, y, z), size, style=_solid(mat) if bottom else _nb(mat))


def prop_wc_toilet(ctx, c, s):
    """A white toilet: the cistern against the wall, the bowl and its seat (lid up), a paper roll on the wall."""
    b = ctx.b
    # (cabin round 2, owner: "it's facing the sink": a toilet is deeper than it's wide, so it faces along its long side)
    f, d, w = _wc_face(ctx, c, (s[2], s[1], s[0]))
    y0 = c[1] - s[1] / 2
    back = -d / 2
    _wc_put(b, c, f, 0, back + 0.1, y0 + 0.6, 0.44, 0.4, 0.2, "bone")                  # cistern
    _wc_put(b, c, f, 0, back + 0.1, y0 + 0.82, 0.47, 0.04, 0.23, "bone")               # its lid
    _wc_put(b, c, f, 0.1, back + 0.1, y0 + 0.85, 0.06, 0.02, 0.04, "steel_light")     # flush button
    _wc_put(b, c, f, 0, back + 0.36, y0 + 0.17, 0.26, 0.34, 0.34, "bone")              # pedestal
    _wc_put(b, c, f, 0, back + 0.44, y0 + 0.37, 0.38, 0.08, 0.5, "bone")               # bowl
    _wc_put(b, c, f, 0, back + 0.46, y0 + 0.4, 0.26, 0.012, 0.32, "trim_dark")         # water in it
    for k in (-1, 1):                                                                    # seat ring sides
        _wc_put(b, c, f, k * 0.16, back + 0.45, y0 + 0.425, 0.06, 0.03, 0.44, "wood_light")
    _wc_put(b, c, f, 0, back + 0.66, y0 + 0.425, 0.38, 0.03, 0.06, "wood_light")
    _wc_put(b, c, f, 0, back + 0.23, y0 + 0.62, 0.38, 0.4, 0.03, "wood_light")         # lid up against the cistern
    _wc_put(b, c, f, w / 2 + 0.05, back + 0.06, y0 + 0.7, 0.04, 0.12, 0.12, "steel_light")   # roll holder
    _wc_put(b, c, f, w / 2 + 0.05, back + 0.12, y0 + 0.66, 0.11, 0.11, 0.11, "bone")


def prop_wc_sink(ctx, c, s):
    """A basin on its pedestal with a tap, a cracked mirror and a soap dish above it."""
    b = ctx.b
    f, w, d = _wc_face(ctx, c, s)
    y0 = c[1] - s[1] / 2
    back = -d / 2
    _wc_put(b, c, f, 0, back + 0.15, y0 + 0.37, 0.16, 0.74, 0.16, "bone")              # pedestal
    _wc_put(b, c, f, 0, back + 0.23, y0 + 0.8, w - 0.04, 0.12, d - 0.02, "bone")       # basin
    _wc_put(b, c, f, 0, back + 0.27, y0 + 0.86, w - 0.16, 0.012, d - 0.16, "trim")    # bowl inside
    _wc_put(b, c, f, 0, back + 0.05, y0 + 0.92, 0.04, 0.1, 0.04, "steel_light")        # tap
    _wc_put(b, c, f, 0, back + 0.1, y0 + 0.96, 0.03, 0.03, 0.12, "steel_light")
    for k in (-1, 1):
        _wc_put(b, c, f, k * 0.12, back + 0.05, y0 + 0.92, 0.05, 0.03, 0.05, "red" if k < 0 else "blue")
    # The mirror (picture on the wall, a steel frame round it).
    at = (c[0] - f[0] * (d / 2 - 0.02), c[2] - f[1] * (d / 2 - 0.02))
    _wc_put(b, c, f, 0, back + 0.006, y0 + 1.45, 0.5, 0.66, 0.01, "trim")
    if f[0] == 0:
        wall_quad(b, (0, 0, f[1]), at[1], c[0] - 0.22, c[0] + 0.22, y0 + 1.15, y0 + 1.75, "decals", ctx.d("wc_mirror"))
    else:
        wall_quad(b, (f[0], 0, 0), at[0], c[2] - 0.22, c[2] + 0.22, y0 + 1.15, y0 + 1.75, "decals", ctx.d("wc_mirror"))
    _wc_put(b, c, f, 0.3, back + 0.06, y0 + 1.05, 0.12, 0.03, 0.1, "steel_light")      # soap shelf


def prop_wc_urinal(ctx, c, s):
    """A wall urinal with its flush pipe."""
    b = ctx.b
    f, w, d = _wc_face(ctx, c, s)
    y0 = c[1] - s[1] / 2
    back = -d / 2
    _wc_put(b, c, f, 0, back + 0.15, y0 + 0.75, 0.38, 0.6, 0.3, "bone")
    _wc_put(b, c, f, 0, back + 0.2, y0 + 0.7, 0.26, 0.4, 0.22, "trim")                # the bowl's inside
    _wc_put(b, c, f, 0, back + 0.04, y0 + 1.3, 0.04, 0.5, 0.04, "steel_light")         # flush pipe


def prop_wc_bath(ctx, c, s):
    """A bath along the wall: the tub, its rim, taps at one end, a shower curtain rail and the curtain bunched up."""
    b = ctx.b
    f, w, d = _wc_face(ctx, c, s)
    y0 = c[1] - s[1] / 2
    _wc_put(b, c, f, 0, 0, y0 + 0.25, w, 0.5, d, "bone")
    _wc_put(b, c, f, 0, 0, y0 + 0.5, w - 0.16, 0.012, d - 0.16, "steel_light")          # the tub's inside
    _wc_put(b, c, f, w / 2 - 0.15, -d / 2 + 0.05, y0 + 0.7, 0.12, 0.05, 0.08, "steel_light")   # taps
    _wc_put(b, c, f, w / 2 - 0.12, -d / 2 + 0.05, y0 + 1.7, 0.08, 0.08, 0.12, "steel_light")   # shower head
    _wc_put(b, c, f, 0, d / 2 - 0.05, y0 + 2.0, w, 0.03, 0.03, "steel_light")            # curtain rail
    _wc_put(b, c, f, -w / 2 + 0.2, d / 2 - 0.05, y0 + 1.3, 0.3, 1.4, 0.08, "blue")   # the curtain, pushed back


def prop_wc_partition(ctx, c, s):
    """A cubicle wall: a laminate panel on legs off the floor, a steel cap."""
    b = ctx.b
    y0 = c[1] - s[1] / 2
    _bx(b, c[0], y0 + 0.15 + (s[1] - 0.15) / 2, c[2], s[0], s[1] - 0.15, s[2], "teal", bottom=True)
    _bx(b, c[0], y0 + s[1] + 0.01, c[2], s[0] + 0.02, 0.02, s[2] + 0.02, "steel_light")
    long_x = s[0] > s[2]
    L = max(s[0], s[2])
    for a in (-L / 2 + 0.08, L / 2 - 0.08):
        _bx(b, c[0] + (a if long_x else 0), y0 + 0.075, c[2] + (0 if long_x else a), 0.04, 0.15, 0.04, "steel_light")


def prop_wc_door(ctx, c, s):
    """An open door leaf (picture only): painted, a steel kick plate and handle."""
    b = ctx.b
    _bx(b, c[0], c[1], c[2], s[0], s[1], s[2], "teal" if BUILDING_NAME[0] in ("school", "offices") else "wood_light")
    long_x = s[0] > s[2]
    L, t = max(s[0], s[2]), min(s[0], s[2])
    for side in (-1, 1):
        o = side * (t / 2 + 0.01)
        for a, y, dims in ((L / 2 - 0.1, c[1] + 0.05, (0.12, 0.03, 0.03)), (0.0, c[1] - s[1] / 2 + 0.15, (L - 0.1, 0.25, 0.01))):
            p = (c[0] + (a if long_x else o), y, c[2] + (o if long_x else a))
            b.box(p, dims if long_x else (dims[2], dims[1], dims[0]), style=_nb("steel_light"))


def _nearest_wet(ctx, c):
    best = min(getattr(ctx, "wet", ()) or [None], key=lambda w: 1e9 if w is None else
               math.hypot(c[0] - (w[0] + w[3]) / 2, c[2] - (w[2] + w[5]) / 2) + (0 if w[1] - 0.1 < c[1] < w[4] + 0.1 else 100))
    return ((best[0] + best[3]) / 2, (best[2] + best[5]) / 2) if best else (c[0], c[2])


def prop_wc_sign(ctx, c, s, decal="wc_sign"):
    """The sign over a washroom door, on the outside: a man and a woman (or one of them), white on blue."""
    mx, mz = _nearest_wet(ctx, c)
    if s[0] > s[2]:
        n = (0, 0, -1 if mz > c[2] else 1)
        wall_quad(ctx.b, n, c[2], c[0] - s[0] / 2, c[0] + s[0] / 2, c[1] - s[1] / 2, c[1] + s[1] / 2, "decals", ctx.d(decal))
    else:
        n = (-1 if mx > c[0] else 1, 0, 0)
        wall_quad(ctx.b, n, c[0], c[2] - s[2] / 2, c[2] + s[2] / 2, c[1] - s[1] / 2, c[1] + s[1] / 2, "decals", ctx.d(decal))


def prop_washroom(ctx, c, s):
    """The room itself: a ceiling lamp (its cover gone), a bin, a towel ring by the door side."""
    b = ctx.b
    y0, y1 = c[1] - s[1] / 2, c[1] + s[1] / 2
    _bx(b, c[0], y1 - 0.03, c[2], 0.3, 0.06, 0.3, "steel_light")
    _bx(b, c[0], y1 - 0.08, c[2], 0.12, 0.05, 0.12, "bone")
    x0, z0 = c[0] - s[0] / 2, c[2] - s[2] / 2
    rng = random.Random(f"wc{c}")
    bx = x0 + 0.25 if rng.random() < 0.5 else c[0] + s[0] / 2 - 0.25
    b.box((bx, y0 + 0.18, z0 + 0.25), (0.26, 0.36, 0.26), yaw=rng.uniform(0, 40), style=_nb("trim_dark"))   # bin
    b.box((bx + 0.35, y0 + 0.03, z0 + 0.35), (0.3, 0.06, 0.24), yaw=rng.uniform(0, 90), pitch=8, style=_nb("bone"))  # loo roll trail


for _k, _f in {"wc_toilet": prop_wc_toilet, "wc_sink": prop_wc_sink, "wc_urinal": prop_wc_urinal, "wc_bath": prop_wc_bath,
               "wc_partition": prop_wc_partition, "wc_door": prop_wc_door, "wc_sign": prop_wc_sign,
               "washroom": prop_washroom,
               "wc_sign_m": lambda ctx, c, s: prop_wc_sign(ctx, c, s, "wc_sign_m"),
               "wc_sign_f": lambda ctx, c, s: prop_wc_sign(ctx, c, s, "wc_sign_f")}.items():
    PROPS[_k] = (lambda f: lambda ctx, c, s, k: f(ctx, c, s))(_f)


def wc_decals(a, rng):
    """Shared decals for the washrooms (every building's atlas): the door sign and the mirror."""
    def figure(c, x0, skirt):
        c.rect(x0 + 1, 9, x0 + 3, 11, "bone")                           # head
        c.rect(x0, 5, x0 + 4, 8, "bone")                                # body
        c.rect(x0 - 1 if skirt else x0, 3, x0 + 5 if skirt else x0 + 4, 5, "bone")
        c.rect(x0, 1, x0 + 1, 3, "bone")                                # legs
        c.rect(x0 + 3, 1, x0 + 4, 3, "bone")

    def one(skirt):       # 0.4 x 0.4 m: just the man (boys', men's) or the woman (girls', women's)
        def paint(c):
            c.rect(0, 0, c.w, c.h, "sky_blue")
            c.frame(0, 0, c.w, c.h, "bone")
            figure(c, 4, skirt)
        return paint

    def sign(c):          # 0.4 x 0.4 m: a man and a woman, white on blue
        c.rect(0, 0, c.w, c.h, "sky_blue")
        c.frame(0, 0, c.w, c.h, "bone")
        for x0, skirt in ((2, False), (7, True)):
            figure(c, x0, skirt)
        c.rect(6, 2, 7, 11, "bone")                                    # the divider
        c.blotch(["steel"], 2, rng, area=(1, 1, c.w - 1, c.h - 1), size=(1, 2))

    def mirror(c):        # 0.44 x 0.6 m: grey-blue glass, a reflection streak, a crack star from a hit
        c.rect(0, 0, c.w, c.h, "steel_light")
        for y in range(c.h):
            for x in range(c.w):
                if (x + y) % 9 < 2:
                    c.put(x, y, "concrete")
        cx, cy = rng.randrange(4, c.w - 4), rng.randrange(6, c.h - 6)
        for ang in range(0, 360, 50):
            dx, dy = math.cos(math.radians(ang + rng.uniform(-10, 10))), math.sin(math.radians(ang))
            for t in range(rng.randrange(4, 9)):
                xx, yy = int(cx + dx * t), int(cy + dy * t)
                if 0 <= xx < c.w and 0 <= yy < c.h:
                    c.put(xx, yy, "iron")
        c.blotch(["sand"], 2, rng, size=(1, 2))
    a.add("wc_sign", 13, 13, sign)
    a.add("wc_sign_m", 13, 13, one(False))
    a.add("wc_sign_f", 13, 13, one(True))
    a.add("wc_mirror", 14, 19, mirror)



# ------------------------------------------------------------------------------------------------ bell tower (0.17)
# The church's bell tower (map 148-158 x 28-38, model origin map (153, 33)): 10 x 10 m, two storeys and the belfry on
# the roof (the lookout): the ringing room downstairs (bell rope, ringers' bench, peal boards), the clock room upstairs
# (the clock frame, rods to the faces), the bell under a stone-piered canopy with a short slate spire. Same stone as
# the church (its look).
TOWER_FP = (-5.0, -5.0, 5.0, 5.0)


def bell_tower_decals(rng):
    a = Atlas(256)

    def dial(c):          # 1.6 m clock face: pale dial, hour marks, a dark ring
        c.rect(0, 0, c.w, c.h, "clear")
        m = (c.w - 1) / 2
        for y in range(c.h):
            for x in range(c.w):
                d = math.hypot(x - m, y - m)
                if d <= m:
                    c.put(x, y, "black" if d > m - 2 else "bone")
        for k in range(12):
            ang = k * math.pi / 6
            for r in range(int(m) - 6, int(m) - 3):
                c.put(round(m + math.cos(ang) * r), round(m + math.sin(ang) * r), "black")

    def peals(c):         # 1.38 x 0.63 m peal board: gold letters on black
        c.rect(0, 0, c.w, c.h, "black")
        c.frame(0, 0, c.w, c.h, "sg_gold")
        ch_text(c, 13, "PEALS RUNG", "sg_gold")
        for y in (3, 6, 9):
            c.rect(4, y, c.w - 4 - (y % 4), y + 1, "bone")

    def ringers(c):       # 1.16 x 0.47 m notice
        c.rect(0, 0, c.w, c.h, "bone")
        ch_text(c, 8, "RINGERS", "black")
        ch_text(c, 2, "TUES 7PM", "red")
    a.add("dial", 51, 51, dial)
    a.add("peals", 44, 20, peals)
    a.add("ringers", 36, 15, ringers)

    def clock_plate(c):   # 0.72 x 0.28 m brass plate on the clock's case (owner: "no idea what that yellow thing is")
        c.rect(0, 0, c.w, c.h, "sg_gold")
        c.frame(0, 0, c.w, c.h, "bronze_dark")
        ch_text(c, 2, "CLOCK", "black")
    a.add("clock_plate", 23, 9, clock_plate)
    add_ch_glass(a)
    return a


def prop_belfry_pier(ctx, c, s):
    """A stone pier at a corner of the belfry (a hair wider than the post it covers), base and capital."""
    b = ctx.b
    dress, ext = ch_look("dress"), ch_look("ext")
    y0 = c[1] - s[1] / 2
    b.box((c[0], c[1], c[2]), (s[0] + 0.1, s[1], s[2] + 0.1), style=lambda n, m, q: (ext, uv_world()))
    b.box((c[0], y0 + 0.1, c[2]), (s[0] + 0.24, 0.2, s[2] + 0.24), style=_nb(dress))
    b.box((c[0], y0 + s[1] - 0.12, c[2]), (s[0] + 0.24, 0.24, s[2] + 0.24), style=_solid(dress))


def prop_belfry_canopy(ctx, c, s):
    """The canopy over the belfry: a stone lintel all round with a shallow arch on each side between the piers,
    boarded underside, the headstock beam the bell hangs from, and a slate spire with a cross (picture only above
    the solid canopy slab)."""
    b = ctx.b
    dress, ext, roof = ch_look("dress"), ch_look("ext"), ch_look("roof")
    y0, top = c[1] - s[1] / 2, c[1] + s[1] / 2
    hx = s[0] / 2
    b.box((c[0], c[1], c[2]), (s[0] + 0.2, s[1], s[2] + 0.2), style=lambda n, m, q: ("wood_dark", uv_world(1.0))
          if n[1] < -0.7 else (dress, uv_world()))
    for k in range(4):                                                        # the arches' spandrels, stepped
        for j in range(6):
            t = (j + 0.5) / 6
            drop = 0.7 * (1 - math.sqrt(max(0.0, 1 - (1 - t) ** 2)))           # deeper near the piers
            if drop < 0.03:
                continue
            for sg in (-1, 1):
                along = sg * (hx - 0.4 - (t * (hx - 0.4)))
                h = 0.15 + drop
                if k < 2:
                    z = (-1 if k == 0 else 1) * (hx - 0.05)
                    b.box((along, y0 - h / 2, z), ((hx - 0.4) / 6 + 0.02, h, 0.3), style=lambda n, m, q: (ext, uv_world()))
                else:
                    x = (-1 if k == 2 else 1) * (hx - 0.05)
                    b.box((x, y0 - h / 2, along), (0.3, h, (hx - 0.4) / 6 + 0.02), style=lambda n, m, q: (ext, uv_world()))
    b.box((0, y0 - 0.12, 0), (s[0] - 0.6, 0.24, 0.3), style=_nb("wood_dark"))           # headstock beam
    apex = top + 4.6
    e = 0.12
    over = 0.3
    x0, x1 = -hx - over, hx + over
    for side in range(4):                                                     # the spire's four faces
        if side == 0:
            pts = [(x0, top, x1), (x1, top, x1), (0, apex, 0)]
        elif side == 1:
            pts = [(x1, top, x0), (x0, top, x0), (0, apex, 0)]
        elif side == 2:
            pts = [(x0, top, x0), (x0, top, x1), (0, apex, 0)]
        else:
            pts = [(x1, top, x1), (x1, top, x0), (0, apex, 0)]
        n = norm(cross(v_sub(pts[1], pts[0]), v_sub(pts[2], pts[0])))
        if n[1] < 0:
            n = v_scale(n, -1)
        b.poly([(p[0], p[1] + e, p[2]) for p in pts], n, roof, uv_slope(4.0))
    b.poly([(x0, top + 0.01, x0), (x1, top + 0.01, x0), (x1, top + 0.01, x1), (x0, top + 0.01, x1)], (0, -1, 0),
           "wood_dark", uv_world(1.0))
    b.box((0, apex + 0.3, 0), (0.08, 0.7, 0.08), style=_nb("black"))                    # cross + weathercock
    b.box((0, apex + 0.45, 0), (0.4, 0.06, 0.06), style=_nb("black"))
    b.box((0, apex + 0.75, 0.05), (0.06, 0.18, 0.35), style=_nb("bronze"))


def prop_bell(ctx, c, s):
    """The bell (bronze, mouth down) hanging from the headstock, with its wheel and the rope going down."""
    b = ctx.b
    top = c[1] + s[1] / 2
    rows = [(0.36, 0.12), (0.42, 0.14), (0.48, 0.16), (0.56, 0.16), (0.66, 0.14), (0.74, 0.1)]
    y = top - 0.25
    for w, h in rows:
        b.box((c[0], y - h / 2, c[2]), (w, h, w), style=lambda n, m, q: ("bronze", uv_world(1.0)))
        y -= h
    b.box((c[0], y - 0.03, c[2]), (0.8, 0.06, 0.8), style=_solid("bronze"))             # the lip
    b.box((c[0], y + 0.1, c[2]), (0.08, 0.3, 0.08), style=_nb("black"))
    b.box((c[0], top - 0.15, c[2]), (0.16, 0.2, 0.16), style=_nb("black"))             # crown
    for k in range(10):                                                         # the wheel beside it
        a = k * math.pi / 5
        b.box((c[0] + 0.5, top - 0.6 + 0.5 * math.sin(a), c[2] + 0.5 * math.cos(a)), (0.05, 0.12, 0.33),
              pitch=math.degrees(a), style=_nb("wood_dark"))
    _beam(b, (c[0] + 0.5, top - 1.1, c[2]), (c[0] + 0.5, top - 1.6, c[2] + 0.5), 0.03, 0.03, "bone")


def prop_ringers_bench(ctx, c, s):
    b = ctx.b
    y0 = c[1] - s[1] / 2
    b.box((c[0], y0 + s[1] - 0.03, c[2]), (s[0], 0.06, s[2]), style=_nb("wood"))
    for z in (c[2] - s[2] / 2 + 0.15, c[2] + s[2] / 2 - 0.15):
        b.box((c[0], y0 + (s[1] - 0.06) / 2, z), (s[0] - 0.05, s[1] - 0.06, 0.06), style=_nb("wood_dark"))
    b.box((c[0] - s[0] / 2 + 0.03, y0 + 0.75, c[2]), (0.05, 0.5, s[2]), style=_nb("wood_dark"))   # back board


def prop_bell_rope(ctx, c, s):
    """The bell rope down through the ceiling, its striped woollen grip (the sally), the tail looped up on a hook."""
    b = ctx.b
    y0, top = c[1] - s[1] / 2, c[1] + s[1] / 2
    b.box((c[0], (top + y0 + 1.2) / 2, c[2]), (0.04, top - y0 - 1.2, 0.04), style=_nb("bone"))
    for k, col in enumerate(("red", "bone", "blue", "red", "bone", "blue")):
        b.box((c[0], y0 + 1.25 + k * 0.1, c[2]), (0.09, 0.1, 0.09), style=_nb(col))
    b.box((c[0], y0 + 0.95, c[2]), (0.04, 0.6, 0.04), style=_nb("bone"))
    b.box((c[0], top - 0.02, c[2]), (0.2, 0.04, 0.2), style=_nb("trim_dark"))           # the hole's guide


def prop_clock_works(ctx, c, s):
    """The tower clock, made to read as a clock at a glance (owner 2026-10-17): a wooden case with a brass CLOCK
    plate, on it the iron movement with big toothed brass wheels, a full clock face on both ends showing the same
    time as the faces outside (10 past 4), the pendulum swinging in the open case, the weights on chains, and the
    rods running out to the faces on the north and south walls."""
    b = ctx.b
    y0 = c[1] - s[1] / 2
    hx, hz = s[0] / 2, s[2] / 2
    case_h = 0.75
    for sx in (-1, 1):                                                          # the case: corner posts, top, back
        for sz in (-1, 1):
            b.box((c[0] + sx * (hx - 0.05), y0 + case_h / 2, c[2] + sz * (hz - 0.05)), (0.1, case_h, 0.1), style=_nb("wood_dark"))
    b.box((c[0], y0 + case_h + 0.03, c[2]), (s[0], 0.06, s[2]), style=_nb("wood_dark"))
    b.box((c[0], y0 + case_h / 2, c[2] - hz + 0.02), (s[0] - 0.2, case_h - 0.1, 0.03), style=_nb("wood"))
    b.box((c[0], y0 + 0.55, c[2] + hz + 0.01), (23 / 32, 9 / 32, 0.02), style=face_decal(ctx.d("clock_plate"), "brass", "+z"))
    b.box((c[0], y0 + case_h - 0.05, c[2]), (0.03, 0.05, 0.03), style=_nb("black"))   # pendulum (in the open case)
    b.box((c[0], y0 + 0.4, c[2]), (0.02, 0.6, 0.02), style=_nb("brass"))
    b.box((c[0], y0 + 0.12, c[2]), (0.2, 0.2, 0.05), style=_nb("brass"))                # its bob
    top = y0 + case_h + 0.06
    for sx in (-1, 1):                                                          # the movement: an iron frame
        for sz in (-1, 1):
            b.box((c[0] + sx * 0.5, top + 0.35, c[2] + sz * 0.25), (0.06, 0.7, 0.06), style=_nb("black"))
        b.box((c[0] + sx * 0.5, top + 0.7, c[2]), (0.06, 0.06, 0.56), style=_nb("black"))
    for sz in (-1, 1):
        b.box((c[0], top + 0.7, c[2] + sz * 0.25), (1.06, 0.06, 0.06), style=_nb("black"))
    for k, (x, y, r, teeth) in enumerate(((-0.2, 0.36, 0.3, 16), (0.22, 0.3, 0.2, 12), (0.18, 0.56, 0.12, 8))):
        z = c[2] + 0.02 + k * 0.06                                               # big toothed wheels, one layer each
        b.box((c[0] + x, top + y, z), (r * 1.6, r * 1.6, 0.04), style=_nb("brass"))
        for t in range(teeth):
            a = t * 2 * math.pi / teeth
            b.box((c[0] + x + math.cos(a) * r, top + y + math.sin(a) * r, z), (0.05, 0.05, 0.035), style=_nb("brass"))
        for t in range(4):                                                      # spokes + the axle
            a = t * math.pi / 4
            _beam(b, (c[0] + x - math.cos(a) * r * 0.75, top + y - math.sin(a) * r * 0.75, z + 0.025),
                  (c[0] + x + math.cos(a) * r * 0.75, top + y + math.sin(a) * r * 0.75, z + 0.025), 0.025, 0.01, "brass")
        b.box((c[0] + x, top + y, z + 0.03), (0.06, 0.06, 0.1), style=_nb("black"))
    dy = top + 0.4                                                               # a clock face on each end
    for sx in (-1, 1):
        xf = c[0] + sx * (hx - 0.12)
        b.box((xf, dy, c[2]), (0.04, 0.5, 0.5), style=_nb("black"))                   # backing plate, round dial
        b.poly([(xf + sx * 0.022, dy - 0.31, c[2] - 0.31), (xf + sx * 0.022, dy - 0.31, c[2] + 0.31),
                (xf + sx * 0.022, dy + 0.31, c[2] + 0.31), (xf + sx * 0.022, dy + 0.31, c[2] - 0.31)],
               (sx, 0, 0), "graffiti", ctx.d("dial"))
        for ang, L, w in ((125.0, 0.15, 0.035), (60.0, 0.24, 0.025)):        # 10 past 4, like the faces outside
            a = math.radians(ang)
            hz_, hy = -math.sin(a) * L * sx, math.cos(a) * L                     # (clockwise as seen from that end)
            _beam(b, (xf + sx * 0.03, dy, c[2]), (xf + sx * 0.03, dy + hy, c[2] + hz_), w, 0.01, "black")
        b.box((xf + sx * 0.035, dy, c[2]), (0.02, 0.04, 0.04), style=_nb("black"))
        _beam(b, (xf, top + 0.7, c[2]), (xf, dy + 0.32, c[2]), 0.04, 0.04, "black")   # (its bracket)
    for sz in (-1, 1):                                                           # the weights on chains
        wz = c[2] + sz * 0.15
        _beam(b, (c[0] - 0.35, top + 0.7, wz), (c[0] - 0.35, y0 + 0.5, wz), 0.015, 0.015, "black")
        b.box((c[0] - 0.35, y0 + 0.35 + (0.15 if sz > 0 else 0), wz), (0.12, 0.3, 0.12), style=_nb("trim_dark"))
    for sz in (-1, 1):                                                           # rods to the faces
        _beam(b, (c[0], top + 0.7, c[2] + sz * 0.25), (c[0], y0 + 1.6, sz * 4.85), 0.03, 0.03, "black")
        b.box((c[0], y0 + 1.6, sz * 4.8), (0.12, 0.12, 0.08), style=_nb("black"))   # (level with the hands)


def prop_passage_wall(ctx, c, s):
    """The covered passage from the tower to the church's west door: a stone wall, plaster inside, coping, a
    little slit window to see out of."""
    b, ext, dress = ctx.b, ch_look("ext"), ch_look("dress")
    out = 1 if c[2] > 1.5 else -1                                               # which face is outside
    b.box(c, s, style=lambda n, m, q: ("ch_plaster" if n[2] * out < -0.5 else ext, uv_world()))
    b.box((c[0], c[1] + s[1] / 2 + 0.04, c[2]), (s[0] + 0.02, 0.08, s[2] + 0.12), style=_nb(dress))
    b.box((c[0], c[1] - s[1] / 2 + 0.25, c[2] + out * (s[2] / 2 + 0.03)), (s[0], 0.5, 0.06), style=_nb(dress))


def prop_passage_roof(ctx, c, s):
    """Its roof: a flat slab under a low slate pitch, a timber ceiling inside, a lamp hook."""
    b = ctx.b
    b.box(c, s, style=lambda n, m, q: ("wood", uv_world()) if n[1] < -0.5 else (ch_look("dress"), uv_world()))
    top, z0, z1 = c[1] + s[1] / 2, c[2] - s[2] / 2 - 0.1, c[2] + s[2] / 2 + 0.1
    ridge = top + 0.45
    for sz, za in ((-1, z0), (1, z1)):                                          # slates both sides of a ridge along x
        b.poly([(c[0] - s[0] / 2, top, za), (c[0] + s[0] / 2, top, za), (c[0] + s[0] / 2, ridge, c[2]),
                (c[0] - s[0] / 2, ridge, c[2])], (0, 0.9, sz * 0.45), ch_look("roof"), uv_world())
    for x in (c[0] - s[0] / 2, c[0] + s[0] / 2):                                # (end triangles, behind the walls)
        b.poly([(x, top, z0), (x, top, z1), (x, ridge, c[2])], (1 if x > c[0] else -1, 0, 0), ch_look("dress"), uv_world())
    b.box((c[0], 0.02, c[2]), (s[0], 0.04, s[2] - 0.4), style=_nb("ch_flags"))      # flagstones underfoot
    for x in (c[0] - 0.45, c[0] + 0.45):                                        # ceiling joists
        b.box((x, c[1] - s[1] / 2 - 0.06, c[2]), (0.1, 0.12, s[2]), style=_nb("wood_dark"))
    b.box((c[0], c[1] - s[1] / 2 - 0.35, c[2]), (0.02, 0.5, 0.02), style=_nb("black"))
    b.box((c[0], c[1] - s[1] / 2 - 0.62, c[2]), (0.18, 0.12, 0.18), style=_nb("black"))


for _k, _f in {"belfry_pier": prop_belfry_pier, "belfry_canopy": prop_belfry_canopy, "bell": prop_bell,
               "ringers_bench": prop_ringers_bench, "bell_rope": prop_bell_rope, "clock_works": prop_clock_works,
               "passage_wall": prop_passage_wall, "passage_roof": prop_passage_roof}.items():
    PROPS[_k] = (lambda f: lambda ctx, c, s, k: f(ctx, c, s))(_f)


def dress_bell_tower(ctx):
    b, rng = ctx.b, random.Random("tower")
    ext, dress = ch_look("ext"), ch_look("dress")
    X = 5.15
    for o in ctx.data.get("openings", []):
        if o["kind"] == "window":
            ch_opening(ctx, o, 0.7, keep=0.4)
        elif o["kind"] == "door":
            ch_opening(ctx, o, 0.6, glass=False)
    for sg in (-1, 1):                                                         # plinth, quoins, string course
        for a0, a1 in (((-X - 0.08, 0.6), (2.4, X + 0.08)) if sg > 0 else ((-X - 0.08, X + 0.08),)):  # (E: passage)
            b.box((sg * (X + 0.04), 0.25, (a0 + a1) / 2), (0.08, 0.5, a1 - a0), style=_nb(dress))
        b.box((sg * (X + 0.05), 3.0, 0), (0.1, 0.16, 2 * X + 0.2), style=_solid(dress))
        if sg < 0:
            b.box((0, 0.25, -(X + 0.04)), (2 * X + 0.16, 0.5, 0.08), style=_nb(dress))
        else:
            for a0, a1 in ((-X - 0.08, -1.2), (1.2, X + 0.08)):
                b.box(((a0 + a1) / 2, 0.25, X + 0.04), (a1 - a0, 0.5, 0.08), style=_nb(dress))
        b.box((0, 3.0, sg * (X + 0.05)), (2 * X + 0.2, 0.16, 0.1), style=_solid(dress))
        b.box((0, 7.05, sg * (X + 0.05)), (2 * X + 0.3, 0.12, 0.3), style=_solid(dress))      # parapet coping
        b.box((sg * (X + 0.05), 7.05, 0), (0.3, 0.12, 2 * X + 0.3), style=_solid(dress))
    for sx in (-1, 1):
        for sz in (-1, 1):
            for k in range(13):
                y = 0.5 + k * 0.5
                lx = k % 2 == 0
                b.box((sx * (X + 0.03) - sx * (0.35 if lx else 0.2) + sx * 0.03, y + 0.24, sz * (X + 0.03)),
                      (0.7 if lx else 0.4, 0.46, 0.06), style=_nb(dress))
                b.box((sx * (X + 0.03), y + 0.24, sz * (X + 0.03) - sz * (0.2 if lx else 0.35) + sz * 0.03),
                      (0.06, 0.44, 0.4 if lx else 0.7), style=_nb(dress))   # (a hair lower: no shared top face)
    for sz in (-1, 1):                                                         # the clock faces (N and S), hands stopped
        z = sz * (X + 0.06)
        for k in range(20):
            a = k * math.pi / 10
            b.box((0.88 * math.cos(a), 4.6 + 0.88 * math.sin(a), z), (0.3, 0.3, 0.1), style=_nb(dress))
        b.poly([(-0.8, 3.8, z + sz * 0.06), (0.8, 3.8, z + sz * 0.06), (0.8, 5.4, z + sz * 0.06), (-0.8, 5.4, z + sz * 0.06)],
               (0, 0, sz), "graffiti", ctx.d("dial"))
        for ang, L, w in ((125.0, 0.42, 0.07), (60.0, 0.66, 0.05)):           # stopped at 10 past 4: hour, minute
            a = math.radians(ang)                                              # (from 12 o'clock, clockwise as seen)
            dx = math.sin(a) * L * (1 if sz > 0 else -1)
            tip = (dx, 4.6 + math.cos(a) * L, z + sz * 0.09)
            ux, uy = (tip[0]) / L, (tip[1] - 4.6) / L                         # along the hand, and across it
            px, py = -uy * w / 2, ux * w / 2
            pts = [(px, 4.6 + py, tip[2]), (-px, 4.6 - py, tip[2]), (tip[0] - px, tip[1] - py, tip[2]), (tip[0] + px, tip[1] + py, tip[2])]
            b.poly(pts, (0, 0, sz), "black", uv_world(1.0))
        b.box((0, 4.6, z + sz * 0.095), (0.1, 0.1, 0.03), style=_nb("black"))                   # the boss
    wq = lambda n, at, a0, a1, y0, y1, reg: wall_quad(b, n, at, a0, a1, y0, y1, "decals", ctx.d(reg))
    wq((1, 0, 0), -4.84, -2.6, -1.225, 1.3, 1.925, "peals")
    wq((1, 0, 0), -4.84, 1.225, 2.6, 1.3, 1.925, "peals")
    wq((0, 0, -1), 4.84, 3.6, 2.475, 1.4, 1.87, "ringers")
    # Ringing room: a table and chairs where the ringers sat, a tea urn; clock room: boxes of old hymn books, a
    # broken chair; the roof: a sniper's nest (sandbags in the north-east corner, casings, a ration tin).
    b.box((-2.8, 0.74, 2.6), (1.4, 0.05, 0.8), style=_nb("wood"))
    for x in (-3.4, -2.2):
        for z in (2.3, 2.9):
            b.box((x, 0.36, z), (0.05, 0.72, 0.05), style=_nb("wood_dark"))
    b.box((-2.5, 0.92, 2.6), (0.24, 0.32, 0.24), style=_nb("steel_light"))
    chair(b, -2.8, 0.0, 1.75, 180, seat="wood_dark", frame="wood_dark")
    chair(b, -1.7, 0.0, 2.6, -90, seat="wood_dark", frame="wood_dark")
    for k, (x, z) in enumerate(((-4.4, -1.6), (-4.4, -1.0), (-3.85, -1.3))):
        b.box((x, 3.0 + 0.2 + (0.4 if k == 2 else 0), z if k < 2 else -1.3), (0.5, 0.4, 0.5), yaw=rng.uniform(-8, 8),
              style=_nb("carton"))
    b.box((3.6, 3.12, -1.6), (0.45, 0.06, 0.45), yaw=30, pitch=70, style=_nb("wood_dark"))
    for k in range(7):
        x = 4.3 - (k % 4) * 0.55
        z = -4.35 + (k // 4) * 0.5 if k < 4 else -4.35
        if k >= 4:
            x, z = 4.35, -3.8 + (k - 4) * 0.55
        b.box((x, 6.12 + (0.2 if k in (1, 5) else 0), z), (0.55, 0.22, 0.35), yaw=90 if k >= 4 else 0, style=_nb("olive"))
    for _ in range(9):
        b.box((rng.uniform(2.5, 4.0), 6.01, rng.uniform(-4.2, -2.8)), (0.03, 0.02, 0.06), yaw=rng.uniform(0, 90), style=_nb("brass"))
    b.box((3.2, 6.06, -3.4), (0.12, 0.1, 0.12), style=_nb("olive_dark"))
    for _ in range(14):                                                        # pigeon mess and feathers up top
        b.box((rng.uniform(-4.3, 4.3), 6.02, rng.uniform(-4.3, 1.5)), (0.12, 0.01, 0.1), style=_nb("bone"))


DECALS["bell_tower"] = bell_tower_decals
DRESSING["bell_tower"] = dress_bell_tower
FOOTPRINTS["bell_tower"] = TOWER_FP
