    wall_quad(b, (0, 0, 1), zf - 0.01, c[0] - 35 / 64, c[0] + 35 / 64, c[1] - 13 / 32, c[1] + 13 / 32, "decals", ctx.d("keys"))
    hx = c[0] + s[0] / 2
